    extra: [{ what: 'The cost shares are illustrative, chosen in the range typical of coffee-shop franchises; they describe no real company.', source: { title: 'Our illustrative store (no outside data)', note: 'the arithmetic is checked by tools/test-domains.mjs' } }],
