// ======================================================================= 5. philosophy
const PHIL = part('Philosophy: arguments as objects', 'Where the analysis of knowledge sits, and the Gettier problem as a navigable argument.', 'How can an argument be explored rather than just read?',
  [['5.1', 'Orientation'], ['5.2', 'The Gettier problem']], [
  { kind: 'definition', title: 'Where the question lives', section: '5.1', visual: { domain: 'philosophy', structure: 'taxonomy', primitive: 'tree' },
    statement: 'The analysis of knowledge belongs to epistemology, the part of philosophy about knowledge and justified belief, beside metaphysics, ethics and logic.',
    explain: [{ text: 'Before an argument, a map. Philosophy divides roughly into metaphysics (what exists), epistemology (what we can know and how), ethics (how we should act) and logic (what follows from what). Inside epistemology one classic question is the analysis of knowledge: what has to be true of a person and a statement for the person to know it, rather than merely believe it or guess it correctly. The rest of this part follows one famous answer, knowledge as justified true belief, and the counterexamples that shook it.',
      figure: { kind: 'tree', caption: 'A small part of the map of philosophy: the question of this part sits under epistemology.', root: { label: 'philosophy', children: [{ label: 'metaphysics', children: [] }, { label: 'epistemology', children: [{ label: 'analysis of knowledge', children: [] }, { label: 'scepticism', children: [] }] }, { label: 'ethics', children: [] }, { label: 'logic', children: [] }] } } }],
    terms: [{ term: 'epistemology', meaning: 'the study of knowledge and justified belief' }],
    opens: 'Is knowledge simply justified true belief?' },
  { title: 'Is justified true belief knowledge?', section: '5.2', visual: { domain: 'philosophy', structure: 'argument_graph', primitive: 'argument_map' },
    statement: 'Gettier\'s cases show beliefs that are justified and true only by luck, so justification, truth and belief are not together sufficient for knowledge; repairs such as "no false lemmas" meet new counterexamples.',
    explain: [{ text: 'The classic analysis says that you know a statement exactly when it is true, you believe it, and you are justified in believing it. The first three conditions look necessary; the weak point is the claim that together they are enough. Gettier\'s first case: Smith has strong evidence that Jones will get the job and that Jones has ten coins in his pocket, so he believes that the man who gets the job has ten coins in his pocket. In fact Smith gets the job, and, unknown to him, he too has ten coins. His belief is justified and true, yet it seems not to be knowledge. Challenge the counterexample and the analysis stands again; accept it and look at the repair and the case that answers the repair.',
      figure: { kind: 'argument_map', caption: 'Press a statement to read it, then challenge it: everything whose support runs through it is marked as affected.', question: 'What is knowledge?',
        nodes: [{ id: 'q', type: 'question', text: 'What is knowledge?' }, { id: 'c', type: 'claim', text: 'S knows p if and only if p is true, S believes p, and S is justified in believing p.', short: 'Knowledge = justified true belief' },
          { id: 'p1', type: 'premise', text: 'If S knows p, then p is true.', short: 'Knowledge requires truth' }, { id: 'p2', type: 'premise', text: 'If S knows p, then S believes p and is justified in believing it.', short: 'It requires justified belief' }, { id: 'p3', type: 'premise', text: 'Justification, truth and belief together are enough for knowledge.', short: 'The three are sufficient' },
          { id: 'o', type: 'objection', text: 'A belief can be justified and true by luck, and then it is not knowledge.', short: 'Luck: justified, true, not knowledge' },
          { id: 'x', type: 'counterexample', text: 'Smith believes, on strong evidence about Jones, that the man who gets the job has ten coins in his pocket; Smith himself gets the job and, unknown to him, has ten coins (Gettier 1963).', short: 'Gettier: the ten coins' },
          { id: 'r', type: 'response', text: 'The belief in the ten-coins case rests on a false lemma (that Jones gets the job); require that the justification rests on no falsehood (Clark 1963).', short: 'No false lemmas' },
          { id: 'rc', type: 'revised', text: 'S knows p if p is true, S believes p, is justified, and the justification depends on no false belief.', short: 'JTB + no false lemma' },
          { id: 'o2', type: 'counterexample', text: 'Fake barns: Henry sees a real barn in a county full of barn façades. He relies on no false belief, yet seems not to know it is a barn (Goldman 1976, after Ginet).', short: 'Fake barns' }],
        links: [{ from: 'c', to: 'q', rel: 'addresses' }, { from: 'p1', to: 'c', rel: 'supports' }, { from: 'p2', to: 'c', rel: 'supports' }, { from: 'p3', to: 'c', rel: 'supports' }, { from: 'o', to: 'p3', rel: 'attacks' }, { from: 'x', to: 'o', rel: 'supports' }, { from: 'r', to: 'rc', rel: 'supports' }, { from: 'rc', to: 'c', rel: 'revises' }, { from: 'o2', to: 'rc', rel: 'attacks' }] } }],
    terms: [{ term: 'necessary condition', meaning: 'one without which the thing cannot hold' }, { term: 'sufficient conditions', meaning: 'conditions that together guarantee the thing' }, { term: 'Gettier case', meaning: 'a justified true belief that is true by luck and so seems not to be knowledge' }],
    intuition: 'A counterexample attacks one premise; everything that leaned on that premise wobbles with it.',
    intuitionFigure: flow('The shape of the debate.', ['claim: JTB', 'counterexample: Gettier', 'revised claim: no false lemma', 'new counterexample: fake barns']),
    check: { q: 'Which premise of the analysis does the ten-coins case attack, and which does it leave alone?', a: 'It attacks sufficiency (justification + truth + belief are enough); it leaves the necessity of each condition untouched: Smith\'s belief is still true, believed and justified.' },
    sources: [SRC.gettier, SRC.clark, SRC.goldman], opens: 'How does evidence become a story without turning into spin?' }]);

// ======================================================================= 6. data and evidence
const CO2 = { years: ['1960', '1970', '1980', '1990', '2000', '2010', '2020', '2023'], ppm: [316.91, 325.68, 338.76, 354.45, 369.71, 390.10, 414.21, 421.08] };
